import { Archive, Boxes, Move, Wrench, ZoomIn } from 'lucide-react';
import { useNavigate, useParams } from 'react-router-dom';
import { useMuseumConfig } from '../../config/ConfigProvider';
import { DevicePage as DeviceStage } from '../../features/devices/DevicePage';
import '../next-device.css';

/**
 * 设备页（新壳）。
 *
 * 三维本体的功能全部由共享的 `features/devices/DevicePage.tsx` 承担——部件面板（14 行、
 * 搜索/显隐/悬停定位/折叠）、拆解滑杆与自动播放、视图预设、部件详情抽屉、关联资料抽屉、
 * 模型资源查看器、加载/诊断/错误与 WebGL 兜底都在里面，并且有 11 例单测兜底。
 * 这里只叠 Concept A 的壳：设备资料卡（规格行 + 米色主 CTA）+ 手势提示条。
 *
 * 走拆解深链（`/devices/:id/disassembly`）时整层 chrome 让开：那条路线的底部属于拆解条
 * （`DevicePage.tsx:235` 的 `keeps-dock` 就是为它准备的）。
 */
export function DevicePage({ active = true, disassemblyEntry = false }: { active?: boolean; disassemblyEntry?: boolean } = {}) {
  const { config } = useMuseumConfig();
  const { deviceId } = useParams();
  const navigate = useNavigate();

  const device = config.devices.find(item => item.id === deviceId) ?? config.devices[0];
  // 设备的关联资料是配置里派生的（`resources[].about` → `device.resourceIds`），直接用。
  const related = device ? config.resources.filter(resource => device.resourceIds.includes(resource.id)) : [];
  const years = related
    .map(resource => resource.period?.year)
    .filter((year): year is number => typeof year === 'number');
  const span = years.length
    ? (Math.min(...years) === Math.max(...years)
        ? `${Math.min(...years)} 年`
        : `${Math.min(...years)} — ${Math.max(...years)}`)
    : '';

  return (
    <section className="next-device">
      <DeviceStage active={active} disassemblyEntry={disassemblyEntry} />
      {!disassemblyEntry && device && (
        <div className="next-device-chrome">
          <article className="next-device-card">
            <span className="next-pill">3D 模型</span>
            <h2>{device.name}</h2>
            <p>{device.summary}</p>
            <ul className="next-device-specs">
              {device.parts.length > 0 && <li><span>部件</span><b>{device.parts.length} 个</b></li>}
              {related.length > 0 && <li><span>关联档案</span><b>{related.length} 件</b></li>}
              {span && <li><span>年代</span><b>{span}</b></li>}
            </ul>
            {/* 没有拆解编排的设备（例如变压器）进拆解页是空面板，主 CTA 改成去看它真正的关联资料。 */}
            {device.parts.length > 0 ? (
              <button
                type="button"
                className="next-primary"
                onClick={() => navigate(`/devices/${device.id}/disassembly`)}
              >
                <Wrench aria-hidden="true" />进入拆解模式
              </button>
            ) : (
              <button
                type="button"
                className="next-primary"
                onClick={() => navigate(related[0] ? `/archive/${related[0].id}` : '/archive')}
              >
                <Archive aria-hidden="true" />查看关联档案
              </button>
            )}
          </article>
          <ul className="next-device-dock" aria-label="模型操作提示">
            <li><Move aria-hidden="true" />拖动旋转</li>
            <li><ZoomIn aria-hidden="true" />滑动缩放</li>
            <li><Boxes aria-hidden="true" />视图预设</li>
          </ul>
        </div>
      )}
    </section>
  );
}

export default DevicePage;
